s+='''\ntest('auction creation uses listing identity and repeats without a duplicate auction',async()=>{row={id,owner_id:uid,status:'active',platform:'avto',title:'Auction vehicle',data:{viewCount:4}};auction=null;const app=await appFor();const payload={listingId:id,platform:'avto',startPrice:27000,durationDays:7,bindingContract:false,cashAllowed:true,auctionType:'live'};const first=await app.inject({method:'POST',url:'/api/auctions',payload});assert.equal(first.statusCode,201);assert.equal(auction?.id,id);assert.equal(auction?.starting_bid,27000);assert.equal(auction?.cash_allowed,false);assert.equal(auction?.listing_fee,0);assert.ok(row?.data.endsAt);assert.equal(row?.data.viewCount,4);const second=await app.inject({method:'POST',url:'/api/auctions',payload});assert.equal(second.statusCode,201);assert.equal(second.json().id,id);await app.close();});\n'''
